// Big Shoulders 500 (fontTools, wght 500): cap 0.8; advances in em.
// Digits sit in fixed 0.46em cells (true tabular), colons in 0.24em cells.
const CAP = 0.8;
const CELL = 0.46;
const COLON = 0.24;
const ADV: Record<string, number> = {
  L: 0.359,
  I: 0.2175,
  V: 0.4405,
  E: 0.3845,
  N: 0.541,
  O: 0.457,
  W: 0.7235,
  " ": 0.212,
  D: 0.453,
  R: 0.4395,
  P: 0.4295,
  S: 0.438,
};
const LSB: Record<string, number> = { L: 0.056, D: 0.056, I: 0.056 };
const RSB: Record<string, number> = { W: 0.0295, N: 0.056, E: 0.0275 };
const TRACK_LIVE = -0.01;

function inkWidth(s: string, track: number) {
  const chars = Array.from(s);
  let w = 0;
  for (const ch of chars) w += ADV[ch] ?? 0.38;
  w += track * Math.max(0, chars.length - 1);
  const first = chars[0] ?? " ";
  const last = chars[chars.length - 1] ?? " ";
  return w - (LSB[first] ?? 0.04) - (RSB[last] ?? 0.04);
}

// Beat sheet (30fps, speed 1, from 5, tick 14):
//   0–6    the clock punches in at 00:00:05 from 1.3× and a blur
//   6–76   every 14 frames: a one-frame inverted flash, a hard cut to the next
//          digit and a new ground colour from the palette, a bump and a shake
//  76–84   00:00:00 holds on black, the digits lit in the gradient
//  84–90   smash: the clock rushes past the lens, LIVE NOW slams in full-bleed
//  92–     logo and url rise; poster hold, the gradient drifts
const SLAM = Easing.bezier(0.22, 1, 0.36, 1);
const RUSH = Easing.bezier(0.6, 0, 0.9, 0.4);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Ground {
  bg: string;
  ink: string;
}

// Dark: gradients.sh "fluted" (bg #050507): #1d2a8f #2f7bff #ff7a3d #ffe2c4.
// Light: gradients.sh "ribbon" (bg #ffffff): #ff3d9a #ff8a3d #ffc83d #7a5cff.
const THEMES = {
  dark: {
    stage: "#0A0A0B",
    ink: "#F3F2EF",
    flash: "#F3F2EF",
    flashInk: "#0A0A0B",
    grounds: [
      {
        bg: "radial-gradient(70% 90% at 80% 10%, #1d2a8f 0%, transparent 70%), #0A0A0B",
        ink: "#F3F2EF",
      },
      {
        bg: "radial-gradient(80% 110% at 18% 0%, #8fb6ff 0%, transparent 62%), #2f7bff",
        ink: "#F3F2EF",
      },
      {
        bg: "radial-gradient(80% 110% at 85% 100%, #ffe2c4 0%, transparent 62%), #ff7a3d",
        ink: "#0A0A0B",
      },
      {
        bg: "radial-gradient(90% 110% at 10% 100%, #ffb98a 0%, transparent 60%), #ffe2c4",
        ink: "#0A0A0B",
      },
      {
        bg: "radial-gradient(80% 110% at 82% 0%, #2f7bff 0%, transparent 64%), #1d2a8f",
        ink: "#F3F2EF",
      },
    ] as Ground[],
    zero: "#050507",
    hero: ["#ffe2c4", "#ff7a3d", "#2f7bff"],
    haze: "#1d2a8f",
    hazeHi: "#2f7bff",
    hazeAlpha: 0.9,
  },
  light: {
    stage: "#F5F4F0",
    ink: "#121214",
    flash: "#121214",
    flashInk: "#F5F4F0",
    grounds: [
      {
        bg: "radial-gradient(70% 90% at 80% 10%, #ffe9f3 0%, transparent 70%), #F5F4F0",
        ink: "#121214",
      },
      {
        bg: "radial-gradient(80% 110% at 18% 0%, #b8a6ff 0%, transparent 62%), #7a5cff",
        ink: "#F5F4F0",
      },
      {
        bg: "radial-gradient(80% 110% at 85% 100%, #ff8a3d 0%, transparent 62%), #ff3d9a",
        ink: "#121214",
      },
      {
        bg: "radial-gradient(90% 110% at 10% 100%, #ff8a3d 0%, transparent 60%), #ffc83d",
        ink: "#121214",
      },
      {
        bg: "radial-gradient(80% 110% at 82% 0%, #ffc83d 0%, transparent 64%), #ff8a3d",
        ink: "#121214",
      },
    ] as Ground[],
    zero: "#F5F4F0",
    hero: ["#7a5cff", "#ff3d9a", "#ff8a3d"],
    haze: "#ff3d9a",
    hazeHi: "#ffc83d",
    hazeAlpha: 0.22,
  },
} as const;

function ramp(t: number, from: number, len: number) {
  return interpolate(t, [from, from + len], [0, 1], CLAMP);
}

/** A short hit: up in 2 frames, eases back over 8. */
function kick(d: number) {
  if (d < 0) return 0;
  if (d < 2) return d / 2;
  const k = Math.max(0, 1 - (d - 2) / 8);
  return k * k;
}

/** A decaying shake that dies in 7 frames. Deterministic. */
function shake(d: number, amp: number, seed: number) {
  if (d < 0 || d > 7) return { x: 0, y: 0 };
  const k = (1 - d / 7) ** 2;
  return {
    x: amp * k * Math.sin(d * 2.7 + seed),
    y: amp * 0.7 * k * Math.cos(d * 3.3 + seed * 1.7),
  };
}

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

const pad = (n: number) => String(Math.max(0, Math.floor(n))).padStart(2, "0");

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function DropTimer(props: DropTimerProps) {
  const {
    label = "DROPS IN",
    from = 5,
    units = ["HRS", "MIN", "SEC"],
    live = "LIVE NOW",
    name = "remocn",
    logo,
    url = "remocn.dev",
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = display,
    scale = 1,
    delay = 0,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    dropTimerTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const u = Math.min(W / 1280, H / 720);
  const c = THEMES[theme];
  const fg = ink ?? c.ink;
  const fill = background === "transparent" ? "transparent" : background;
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, "");

  const total = secondsOf(from);
  const enterEl = tl.get("enter");
  const ticks = Array.from({ length: total }, (_, k) =>
    tl.get(`tick:${k + 1}`),
  );
  const smash = tl.get("smash");
  const liveEl = tl.get("live");
  const smashAt = smash.start;

  // ── Clock state ──
  // The second on the clock is the last tick to have started.
  let tickIdx = 0;
  for (let k = 1; k <= total; k++) if (t >= ticks[k - 1].start) tickIdx = k;
  const left = total - tickIdx;
  const current = tickIdx > 0 ? ticks[tickIdx - 1] : undefined;
  const lastTick = current ? current.start : enterEl.end;
  const sinceTick = t - lastTick;
  const isFlash =
    current !== undefined &&
    sinceTick >= 0 &&
    sinceTick < current.beat("flash");
  const atZero = left === 0;
  const ground = c.grounds[tickIdx % c.grounds.length];

  const hh = Math.floor(left / 3600);
  const mm = Math.floor((left % 3600) / 60);
  const ss = left % 60;
  const clock = `${pad(hh)}:${pad(mm)}:${pad(ss)}`;

  // ── Clock layout: fixed cells, fitted to the frame width ──
  const cells = Array.from(clock).map((ch) => (ch === ":" ? COLON : CELL));
  const clockEm = cells.reduce((a, b) => a + b, 0);
  const fs = Math.min((0.9 * W) / clockEm, (0.56 * H) / CAP);
  const clockW = clockEm * fs;
  const clockX = (W - clockW) / 2;
  const capH = CAP * fs;
  const baseline = H * 0.5 + capH * 0.5 + 0.02 * H;
  let cx = clockX;
  const glyphs = Array.from(clock).map((ch, i) => {
    const mid = cx + (cells[i] * fs) / 2;
    cx += cells[i] * fs;
    return { ch, mid, i };
  });
  const pairMid = [0, 3, 6].map((i) => (glyphs[i].mid + glyphs[i + 1].mid) / 2);

  // ── Camera ──
  const enter = SLAM(ramp(t, enterEl.start, enterEl.length));
  const enterBlur = (1 - enter) * 16;
  const cameraAt = (tt: number) => {
    let bump = 0;
    let sx = 0;
    let sy = 0;
    for (let k = 1; k <= total; k++) {
      const d = tt - ticks[k - 1].start;
      if (d < -1 || d > 12) continue;
      // hits grow as the clock runs out
      const g = 0.7 + (0.6 * k) / total;
      bump = Math.max(bump, g * kick(d));
      const s = shake(d, 6 * u * g, k * 1.3);
      sx += s.x;
      sy += s.y;
    }
    const smashD = tt - smashAt;
    bump = Math.max(bump, 1.4 * kick(smashD - smash.beat("hit")));
    const s3 = shake(smashD - smash.beat("hit"), 12 * u, 4.4);
    sx += s3.x;
    sy += s3.y;
    return { sx, sy, k: 1 + 0.04 * bump };
  };
  const cam = cameraAt(t);
  const { sx, sy } = cam;
  const camScale = cam.k;
  // A frame either side, in the clock's own time; the scale is weighed by
  // the half-width it swings the frame's edge through.
  const camMoves = (o: ReturnType<typeof cameraAt>) =>
    Math.abs(o.sx - sx) > 1e-3 ||
    Math.abs(o.sy - sy) > 1e-3 ||
    Math.abs(o.k - camScale) * W > 1e-3;
  const camMoving =
    camMoves(cameraAt(t + speed)) || camMoves(cameraAt(Math.max(0, t - speed)));

  // ── Smash ──
  const rush = RUSH(ramp(t, smashAt, smash.length));
  const clockScaleAt = (tt: number) =>
    (1.3 - 0.3 * SLAM(ramp(tt, enterEl.start, enterEl.length))) *
    (1 + 1.8 * RUSH(ramp(tt, smashAt, smash.length)));
  const clockScale = clockScaleAt(t);
  const clockMoving =
    clockScaleAt(t + speed) !== clockScale ||
    clockScaleAt(Math.max(0, t - speed)) !== clockScale;
  const clockBlur = enterBlur + 26 * rush;
  const clockOpacity = Math.min(
    ramp(t, enterEl.start, enterEl.beat("fade")),
    1 - ramp(t, smashAt + smash.beat("clockOutAt"), smash.beat("clockOut")),
  );
  const liveP = SLAM(ramp(t, liveEl.start, liveEl.length));
  const liveScale = 1.7 - 0.7 * liveP;
  const liveBlur = (1 - liveP) * 18;
  const liveOpacity = ramp(t, liveEl.start, liveEl.beat("fade"));
  const flashSmash = interpolate(
    t,
    [
      smashAt,
      smashAt + smash.beat("flashPeak"),
      smashAt + smash.beat("flashOut"),
    ],
    [0, 1, 0],
    CLAMP,
  );
  const after = t >= liveEl.start;
  const brandEl = tl.get("brand");
  const urlEl = tl.get("url");
  const rise = (e: typeof brandEl) => SLAM(ramp(t, e.start, e.length));
  const lift = (e: typeof brandEl) =>
    `translateY(${(1 - rise(e)) * 14 * u}px)${glide(midway(ramp(t, e.start, e.length)) && !camMoving)}`;
  const drift = ramp(t, smashAt, smash.beat("drift"));
  const haze = SLAM(ramp(t, liveEl.start, liveEl.beat("haze")));

  // ── Payoff layout ──
  const liveEm = inkWidth(live.toUpperCase(), TRACK_LIVE);
  const liveFs = Math.min((0.9 * W) / liveEm, (0.5 * H) / CAP);
  const liveCap = CAP * liveFs;
  const liveBase = H * 0.535 + liveCap * 0.5;

  const bgNow = after
    ? (fill ?? c.zero)
    : isFlash
      ? c.flash
      : atZero
        ? (fill ?? c.zero)
        : (fill ?? ground.bg);
  const groundInk = fill === undefined ? ground.ink : fg;
  const digitInk = isFlash ? c.flashInk : groundInk;
  const labelInk = isFlash ? c.flashInk : atZero ? fg : groundInk;

  const heroGrad = `${uid}hero`;
  const zeroGrad = `${uid}zero`;

  return (
    <AbsoluteFill style={{ background: fill ?? c.stage, overflow: "hidden" }}>
      <div style={{ position: "absolute", inset: 0, background: bgNow }} />
      {/* Payoff haze rising from the bottom. */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: after ? haze * c.hazeAlpha : 0,
          background: [
            `radial-gradient(60% 50% at ${44 + 10 * drift}% ${122 - 18 * haze}%, ${c.hazeHi} 0%, transparent 70%)`,
            `radial-gradient(95% 70% at 50% ${130 - 16 * haze}%, ${c.haze} 0%, transparent 76%)`,
          ].join(", "),
        }}
      />

      <ScaleLayer scale={scale}>
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: `translate(${sx}px, ${sy}px) scale(${camScale})${glide(camMoving)}`,
            transformOrigin: "50% 50%",
          }}
        >
          <svg
            width={W}
            height={H}
            viewBox={`0 0 ${W} ${H}`}
            style={{ position: "absolute", inset: 0, overflow: "visible" }}
            role="img"
            aria-label={
              after ? `${live} — ${name} ${url}` : `${label} ${clock}`
            }
          >
            <defs>
              <linearGradient
                id={zeroGrad}
                gradientUnits="userSpaceOnUse"
                x1={clockX}
                y1={baseline - capH}
                x2={clockX + clockW}
                y2={baseline}
              >
                <stop offset="0" stopColor={c.hero[2]} />
                <stop offset="0.55" stopColor={c.hero[1]} />
                <stop offset="1" stopColor={c.hero[0]} />
              </linearGradient>
              <linearGradient
                id={heroGrad}
                gradientUnits="userSpaceOnUse"
                x1={W * (0.02 + 0.06 * drift)}
                y1={liveBase}
                x2={W * (0.92 + 0.06 * drift)}
                y2={liveBase - liveCap}
              >
                <stop offset="0" stopColor={c.hero[1]} />
                <stop offset="0.62" stopColor={c.hero[0]} />
                <stop offset="1" stopColor={c.hero[0]} />
              </linearGradient>
            </defs>

            {/* The clock. */}
            {t < smashAt + smash.beat("gone") ? (
              <g
                style={{
                  transform: `scale(${clockScale})${glide(clockMoving && !camMoving)}`,
                  transformOrigin: `${W / 2}px ${baseline - capH / 2}px`,
                  filter:
                    clockBlur > 0.2 ? `blur(${clockBlur * u}px)` : undefined,
                }}
                opacity={clockOpacity}
              >
                <text
                  x={W / 2}
                  y={baseline - capH - 0.075 * H}
                  textAnchor="middle"
                  fontFamily={fontFamily}
                  fontWeight={500}
                  fontSize={0.068 * H}
                  fill={labelInk}
                  style={{ letterSpacing: "0.08em" }}
                >
                  {label}
                </text>
                <g
                  fontFamily={fontFamily}
                  fontWeight={500}
                  fontSize={fs}
                  textAnchor="middle"
                  fill={atZero && !isFlash ? `url(#${zeroGrad})` : digitInk}
                >
                  {glyphs.map((g) => (
                    <text
                      key={g.i}
                      x={g.mid}
                      y={g.ch === ":" ? baseline - 0.035 * fs : baseline}
                    >
                      {g.ch}
                    </text>
                  ))}
                </g>
                <g
                  fontFamily={mono}
                  fontWeight={400}
                  fontSize={0.03 * H}
                  textAnchor="middle"
                  fill={labelInk}
                  opacity={0.8}
                  style={{ letterSpacing: "0.14em" }}
                >
                  {units.map((un, i) => (
                    <text key={un} x={pairMid[i]} y={baseline + 0.075 * H}>
                      {un}
                    </text>
                  ))}
                </g>
              </g>
            ) : null}

            {/* LIVE NOW, full-bleed. */}
            {after ? (
              <text
                x={W / 2}
                y={liveBase}
                textAnchor="middle"
                fontFamily={fontFamily}
                fontWeight={500}
                fontSize={liveFs}
                fill={`url(#${heroGrad})`}
                opacity={liveOpacity}
                style={{
                  letterSpacing: `${TRACK_LIVE}em`,
                  transform: `scale(${liveScale})${glide(midway(liveP) && !camMoving)}`,
                  transformOrigin: `${W / 2}px ${liveBase - liveCap / 2}px`,
                  filter:
                    liveBlur > 0.2 ? `blur(${liveBlur * u}px)` : undefined,
                }}
              >
                {live.toUpperCase()}
              </text>
            ) : null}
          </svg>

          {/* Brand over the payoff. */}
          {after ? (
            <div
              style={{
                position: "absolute",
                left: 0,
                right: 0,
                top: liveBase - liveCap - 0.135 * H,
                display: "flex",
                justifyContent: "center",
                opacity: rise(brandEl),
                transform: lift(brandEl),
              }}
            >
              {logo ??
                (name.trim().toLowerCase() === "remocn" ? (
                  <RemocnLogo fontSize={0.064 * H} color={fg} />
                ) : (
                  <span
                    style={{
                      fontFamily,
                      fontWeight: 500,
                      fontSize: 0.064 * H,
                      color: fg,
                      lineHeight: 1,
                    }}
                  >
                    {name}
                  </span>
                ))}
            </div>
          ) : null}

          {/* Url under the payoff. */}
          {after ? (
            <div
              style={{
                position: "absolute",
                left: 0,
                right: 0,
                top: liveBase + 0.075 * H,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                gap: 12 * u,
                fontFamily: mono,
                fontWeight: 400,
                fontSize: 0.032 * H,
                letterSpacing: "0.04em",
                color: fg,
                lineHeight: 1,
                opacity: rise(urlEl),
                transform: lift(urlEl),
              }}
            >
              <div
                style={{
                  width: 0.016 * H,
                  height: 0.016 * H,
                  borderRadius: 99,
                  background: accent,
                  opacity:
                    0.8 + 0.2 * Math.cos(((t - smashAt) / 22) * Math.PI * 2),
                }}
              />
              {url}
            </div>
          ) : null}
        </div>
      </ScaleLayer>

      {/* The smash flash. */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: c.flash,
          opacity: flashSmash,
        }}
      />
    </AbsoluteFill>
  );
}
